  const pinMatch = query.match(/pin[:\s]+(\d{4})/i);
  userId = userIdMatch ? userIdMatch[1] : '';
  pin = pinMatch ? pinMatch[1] : '';
}

const mockUsers = {
  "5673": { name: "Devin", pin: "1234" },
  "8841": { name: "Priya", pin: "0420" },
  "3392": { name: "Aditya", pin: "7890" }
};

// Do the verification in the tool itself
if (!userId || !pin) {
  return JSON.stringify({
    verified: false,
    reason: "Missing userId or PIN"
  });
}

const user = mockUsers[userId];

if (!user) {
  return JSON.stringify({
    verified: false,
    reason: "User ID not found"
  });
}

if (user.pin !== pin) {
  return JSON.stringify({
    verified: false,
