  .replace(/```/g, '')
  .replace(/\{\{/g, '{')
  .replace(/\}\}/g, '}')
  .replace(/'/g, '"')
  .trim();

// Try to parse JSON first
let authResult = null;
try {
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    authResult = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  authResult = null;
}

// If JSON parsing failed or gave wrong result,
// try to detect success/failure from plain text
let isSuccess = false;
let successUserId = null;
let successName = null;

if (authResult && authResult.authResult === 'success') {
  // Clean JSON success
  isSuccess = true;
  successUserId = authResult.userId;
  successName = authResult.name;
} else if (authResult && authResult.verified === true) {
  // Tool response leaked through
  isSuccess = true;
  successUserId = authResult.userId;
  successName = authResult.name;
} else {
  // Try plain text detection
  const lowerOutput = cleaned.toLowerCase();
  const successSignals = [
    'authenticated successfully',
    'authentication successful',
    'verified successfully',
    'successfully authenticated',
    'login successful',
    'you are now authenticated',
    'welcome',
    'how can i assist',
    'how can i help'
  ];

  const hasSuccessSignal = successSignals.some(s => lowerOutput.includes(s));

  if (hasSuccessSignal) {
    isSuccess = true;
    // Extract userId and name from the tool response stored in logs
    // Try to find them in the output text
    const userIdMatch = rawOutput.match(/user id[:\s]+(\d+)/i) ||
                        rawOutput.match(/"userId"[:\s]+"(\d+)"/i) ||
                        rawOutput.match(/id is (\d+)/i);
    const nameMatch = rawOutput.match(/name is ([A-Za-z]+)/i) ||
                      rawOutput.match(/"name"[:\s]+"([A-Za-z]+)"/i) ||
                      rawOutput.match(/your name[:\s]+([A-Za-z]+)/i);

    successUserId = userIdMatch ? userIdMatch[1] : null;
    successName = nameMatch ? nameMatch[1] : null;

    // If we still can't find name/userId from output,
    // get it from the Build State's last known values
    if (!successUserId) successUserId = buildState.auth?.userId;
    if (!successName) successName = buildState.auth?.name;

    // Last resort — look up from the user message
    if (!successUserId) {
      const msgMatch = $('When chat message received').first().json.chatInput
        .match(/\b(\d{4})\b/);
      successUserId = msgMatch ? msgMatch[1] : null;
    }
  }
}

let newFailedAttempts = buildState.auth?.failedAttempts ?? 0;
let nextStage;
let replyText;

if (isSuccess) {
  nextStage = 'INTENT_CAPTURE';
  replyText = `Hi ${successName ?? 'there'}, how can I help you today?`;
} else {
  newFailedAttempts += 1;
  if (newFailedAttempts >= 3) {
