const sessionId = $('When chat message received').first().json.sessionId;
const buildState = $('Build State').first().json;
const rawOutput = $input.first().json.output;

// Mark the current date_time intent as done
const intents = buildState.intents ?? [];
const updated = intents.map(i => {
  if (i.type === 'date_time' && i.status === 'pending') {
    return { ...i, status: 'done' };
  }
  return i;
});

return [{
  json: {
    sessionId,
    stage: 'INTENT_HANDLER',
    authenticated: buildState.auth?.authenticated ?? true,
    userId: buildState.auth?.userId,
    name: buildState.auth?.name,
    failedAttempts: buildState.auth?.failedAttempts ?? 0,
    intents: JSON.stringify(updated),
    intentRetryCount: buildState.intentRetryCount ?? 0,
    turnCount: buildState.turnCount ?? 1,
    lastAgentResponse: rawOutput,
    output: rawOutput
  }
}];

const queryText = query.toLowerCase().trim();

let actualQuery = queryText;
let now = new Date();

// Handle date passed via ||| separator
if (queryText.includes('|||')) {
  const parts = queryText.split('|||');
  actualQuery = parts[0].trim();
  const dateStr = parts[1].trim();
  if (dateStr && dateStr.match(/^\d{4}-\d{2}-\d{2}$/)) {
    now = new Date(dateStr + 'T12:00:00Z');
  }
}

let result = new Date(now);
let description = '';

if (actualQuery.includes('tomorrow')) {
  result.setUTCDate(now.getUTCDate() + 1);
  description = 'tomorrow';
} else if (actualQuery.includes('yesterday')) {
  result.setUTCDate(now.getUTCDate() - 1);
  description = 'yesterday';
} else if (actualQuery === 'today') {
  result = new Date(now);
  description = 'today';
} else if (/(\d+)\s*hour/.test(actualQuery)) {
  const h = parseInt(actualQuery.match(/(\d+)\s*hour/)[1], 10);
  result = new Date(now.getTime() + h * 3600 * 1000);
  description = `${h} hour(s) from now`;
} else if (/(\d+)\s*day/.test(actualQuery)) {
  const d = parseInt(actualQuery.match(/(\d+)\s*day/)[1], 10);
  result.setUTCDate(now.getUTCDate() + d);
  description = `${d} day(s) from now`;
} else if (/(\d+)\s*minute/.test(actualQuery)) {
  const m = parseInt(actualQuery.match(/(\d+)\s*minute/)[1], 10);
  result = new Date(now.getTime() + m * 60 * 1000);
  description = `${m} minute(s) from now`;
} else {
  const days = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
  const target = days.findIndex(d => actualQuery.includes(d));
  if (target >= 0) {
    const todayDay = now.getUTCDay();
    let diff = (target - todayDay + 7) % 7;
    if (diff === 0) diff = 7;
    if (actualQuery.includes('next') && !actualQuery.includes('coming')) {
      diff = diff + 7;
    }
    result.setUTCDate(now.getUTCDate() + diff);
    description = days[target];
  } else {
    return JSON.stringify({
      success: false,
      error: 'Could not understand the date query: ' + query
    });
  }
}

const formatted = result.toLocaleDateString('en-GB', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'UTC'
});

return JSON.stringify({
  success: true,
  query: actualQuery,
  resolved: formatted,
  isoDate: result.toISOString().split('T')[0],
  description
});

