const sessionId = $('When chat message received').first().json.sessionId;
const buildState = $('Build State').first().json;
const rawOutput = $input.first().json.output;
const userMessage = $('When chat message received').first().json.chatInput;
const userMessageLower = userMessage.toLowerCase();

// Parse agent JSON output
let parsedResult = null;
try {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedResult = JSON.parse(jsonMatch[0].replace(/'/g, '"'));
  }
} catch(e) {
  parsedResult = null;
}

// Detect new intents in user message
const currencyCodes = ['USD','EUR','GBP','INR','JPY','AUD','CAD','CHF','CNY','SGD','HKD','NZD','SEK','NOK','DKK'];
const dateKeywords = ['yesterday','tomorrow','monday','tuesday','wednesday','thursday','friday','saturday','sunday','next','coming','hour','minute','week'];

const hasCurrency = userMessageLower.includes('convert') ||
                    userMessageLower.includes('conversion') ||
                    userMessageLower.includes('exchange') ||
                    userMessageLower.includes('rate') ||
                    currencyCodes.filter(c => userMessageLower.includes(c.toLowerCase())).length >= 1;

const hasDateKeyword = dateKeywords.some(k => userMessageLower.includes(k));
const hasDateWord = userMessageLower.includes('date') || userMessageLower.includes('when');
const hasDate = hasDateKeyword || hasDateWord;
const userHasNewIntents = hasCurrency || hasDate;

// Detect clear NO signals
const isUserNo = /\b(no|nope|nothing|that'?s?\s*(it|all|fine|good)|thank\s*you|thanks|goodbye|bye|done|i'?m?\s*(good|fine|all\s*set)|nothing\s*else|no\s*more|not\s*really|all\s*done)\b/.test(userMessageLower);

// Simple yes
const isSimpleYes = /^(yes|yeah|yep|sure|please|more|another|add|ok|okay)[\s\.\!\?]*$/.test(userMessageLower.trim());

// Check if agent is asking a question
const agentIsAsking = rawOutput.toLowerCase().includes('anything else') ||
                      rawOutput.toLowerCase().includes('can i help') ||
                      rawOutput.toLowerCase().includes('would you like') ||
                      rawOutput.toLowerCase().includes('is there') ||
                      rawOutput.toLowerCase().includes('anything i can');

// If user has new intents — extract them right now
// Run Intent Extractor logic inline so we don't lose the message
let extractedIntents = [];

if (userHasNewIntents) {
  if (hasCurrency) {
    const foundCurrencies = currencyCodes.filter(c =>
      userMessageLower.includes(c.toLowerCase())
    );
    let from = 'USD';
    let to = 'INR';
    if (foundCurrencies.length >= 2) {
      const toPattern = new RegExp(`(${foundCurrencies[0]})\\s+to\\s+(${foundCurrencies[1]})`, 'i');
      const reversePattern = new RegExp(`(${foundCurrencies[1]})\\s+to\\s+(${foundCurrencies[0]})`, 'i');
      if (toPattern.test(userMessage)) { from = foundCurrencies[0]; to = foundCurrencies[1]; }
      else if (reversePattern.test(userMessage)) { from = foundCurrencies[1]; to = foundCurrencies[0]; }
      else { from = foundCurrencies[0]; to = foundCurrencies[1]; }
    } else if (foundCurrencies.length === 1) {
      from = foundCurrencies[0];
    }
    let date = 'latest';
    if (userMessageLower.includes('yesterday')) date = 'yesterday';
    else if (userMessageLower.includes('today')) date = 'today';
    extractedIntents.push({ type: 'currency_conversion', params: { from, to, date }, status: 'pending' });
  }

  if (hasDate) {
    const cleanMessage = userMessageLower
      .replace(/convert|conversion|exchange|rate/g, '')
      .replace(/[a-z]{3}\s+to\s+[a-z]{3}/g, '')
      .trim();
    const words = cleanMessage.split(/\s+/);
    let dateWords = [];
    let capturing = false;
    const allDateKeywords = [...dateKeywords, 'today'];
    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      if (allDateKeywords.some(k => word === k || word.startsWith(k))) capturing = true;
      if (capturing) {
        if (['and','for','also','plus'].includes(word) && dateWords.length > 0) break;
        dateWords.push(words[i]);
        if (dateWords.length >= 4) break;
      }
    }
    let query = dateWords.join(' ').trim();
    if (!query) query = 'today';
    if (query !== 'this' && query !== 'a' && query !== 'the') {
      extractedIntents.push({ type: 'date_time', params: { query }, status: 'pending' });
    }
  }
}

let nextStage;
let replyText;
let newIntents = buildState.intents ?? [];

if (userHasNewIntents && extractedIntents.length > 0) {
  // Extract intents inline and go straight to INTENT_CONFIRM
  newIntents = newIntents.filter(i => i.status !== 'done');
  for (const incoming of extractedIntents) {
    const alreadyExists = newIntents.some(e => e.type === incoming.type);
    if (!alreadyExists) newIntents.push(incoming);
  }
  const intentSummary = newIntents.map((i, idx) => {
    if (i.type === 'currency_conversion') return `${idx+1}. Currency conversion: ${i.params.from} to ${i.params.to}${i.params.date !== 'latest' ? ` for ${i.params.date}` : ''}`;
    if (i.type === 'date_time') return `${idx+1}. Date/time: ${i.params.query}`;
    return `${idx+1}. ${i.type}`;
  }).join('\n');
  nextStage = 'INTENT_CONFIRM';
  replyText = `Sure! Here's what I detected:\n${intentSummary}\n\nShall I proceed?`;

} else if (isUserNo || (parsedResult && parsedResult.hasMoreIntents === false)) {
  nextStage = 'END';
  replyText = 'Thank you for using our service. Have a great day!';

} else if (agentIsAsking && isSimpleYes) {
  nextStage = 'WRAPUP';
  replyText = rawOutput;

} else if (isSimpleYes || (parsedResult && parsedResult.hasMoreIntents === true)) {
  newIntents = newIntents.filter(i => i.status !== 'done');
  nextStage = 'INTENT_CAPTURE';
  replyText = `Sure! What else can I help you with?`;

} else if (agentIsAsking && !parsedResult) {
  nextStage = 'WRAPUP';
  replyText = rawOutput;

} else {
  nextStage = 'WRAPUP';
  replyText = rawOutput;
}

return [{
  json: {
    sessionId,
    stage: nextStage,
    authenticated: buildState.auth?.authenticated ?? true,
    userId: buildState.auth?.userId,
    name: buildState.auth?.name,
    failedAttempts: buildState.auth?.failedAttempts ?? 0,
    intents: JSON.stringify(newIntents),
    intentRetryCount: buildState.intentRetryCount ?? 0,
    turnCount: buildState.turnCount ?? 1,
    lastAgentResponse: replyText,
    output: replyText
  }
}];

return [{
  json: {
    output: "This conversation has ended. Thank you."
  }
}];

