      `(${foundCurrencies[0]})\\s+to\\s+(${foundCurrencies[1]})`, 'i'
    );
    const reversePattern = new RegExp(
      `(${foundCurrencies[1]})\\s+to\\s+(${foundCurrencies[0]})`, 'i'
    );
    if (toPattern.test(userMessage)) {
      from = foundCurrencies[0]; to = foundCurrencies[1];
    } else if (reversePattern.test(userMessage)) {
      from = foundCurrencies[1]; to = foundCurrencies[0];
    } else {
      from = foundCurrencies[0]; to = foundCurrencies[1];
    }
  } else if (foundCurrencies.length === 1) {
    from = foundCurrencies[0];
  }

  // Detect currency date — including specific years and full dates
  if (userMessageLower.includes('yesterday')) {
    currencyDate = 'yesterday';
  } else if (userMessageLower.includes('today')) {
    currencyDate = 'today';
  } else {
    // Check for full date pattern YYYY-MM-DD
    const fullDateMatch = userMessage.match(/\b(\d{4}-\d{2}-\d{2})\b/);
    if (fullDateMatch) {
      currencyDate = fullDateMatch[1];
    } else {
      // Check for year only (e.g. "for 2012", "in 2015")
      const yearMatch = userMessage.match(/\b(19\d{2}|20\d{2})\b/);
      if (yearMatch) {
        // Use Jan 1st of that year as the date
        currencyDate = `${yearMatch[1]}-01-01`;
      }
    }
  }

  detectedIntents.push({
    type: 'currency_conversion',
    params: { from, to, date: currencyDate },
    status: 'pending'
  });
}

if (hasDate) {
  let cleanMessage = userMessageLower
    .replace(/convert|conversion|exchange|rate/g, '')
    .replace(/[a-z]{3}\s+to\s+[a-z]{3}/g, '')
    .trim();

  // Remove currency date keywords to avoid bleed
  if (hasCurrency && currencyDate === 'yesterday') {
    cleanMessage = cleanMessage.replace(/\byesterday\b/, '');
  }
  if (hasCurrency && currencyDate === 'today') {
    cleanMessage = cleanMessage.replace(/\btoday\b/, '');
  }
  // Remove year if it was used for currency
  if (hasCurrency && currencyDate.match(/^\d{4}-\d{2}-\d{2}$/) && currencyDate.includes('-01-01')) {
    const year = currencyDate.split('-')[0];
    cleanMessage = cleanMessage.replace(new RegExp(`\\b${year}\\b`, 'g'), '');
  }

  const words = cleanMessage.split(/\s+/);
  let dateWords = [];
  let capturing = false;
  const allDateKeywords = [...dateKeywords, 'today'];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (allDateKeywords.some(k => word === k || word.startsWith(k))) {
      capturing = true;
    }
    if (capturing) {
      if (['and','for','also','plus'].includes(word) && dateWords.length > 0) break;
      dateWords.push(words[i]);
      if (dateWords.length >= 4) break;
    }
  }

  let query = dateWords.join(' ').trim();
  if (!query) query = 'today';

  if (query !== 'this' && query !== 'a' && query !== 'the' && query !== '') {
    detectedIntents.push({
      type: 'date_time',
      params: { query },
      status: 'pending'
    });
  }
}

// Merge with existing intents
const merged = [...existingIntents];
for (const incoming of detectedIntents) {
  const alreadyExists = merged.some(e => e.type === incoming.type);
  if (!alreadyExists) merged.push(incoming);
}

// Build intent summary
const intentSummary = merged.map((i, idx) => {
  if (i.type === 'currency_conversion') {
    return `${idx + 1}. Currency conversion: ${i.params.from} to ${i.params.to}${i.params.date !== 'latest' ? ` for ${i.params.date}` : ''}`;
  }
  if (i.type === 'date_time') {
    return `${idx + 1}. Date/time: ${i.params.query}`;
  }
  return `${idx + 1}. ${i.type}`;
}).join('\n');

let nextStage;
let replyText;

if (merged.length > 0) {
  nextStage = 'INTENT_CONFIRM';
  replyText = `Sure ${name}! Here's what I detected:\n${intentSummary}\n\nShall I proceed? You can also say:\n- "remove currency" or "remove date" to remove an intent\n- "add [something]" to add more`;
} else {
  nextStage = 'INTENT_CAPTURE';
  replyText = `I'm sorry ${name}, I couldn't detect any supported intents. I can help with:\n1. Currency conversion (e.g. "convert USD to INR")\n2. Date/time questions (e.g. "what date is next Monday?")\n\nPlease try again.`;
}

return [{
  json: {
    sessionId,
    stage: nextStage,
    authenticated: buildState.auth?.authenticated ?? true,
    userId: buildState.auth?.userId,
    name: buildState.auth?.name,
    failedAttempts: buildState.auth?.failedAttempts ?? 0,
    intents: JSON.stringify(merged),
    intentRetryCount: buildState.intentRetryCount ?? 0,
    turnCount: buildState.turnCount ?? 1,
    lastAgentResponse: replyText,
    intentSummary,
    output: replyText
  }
}];

const sessionId = $('When chat message received').first().json.sessionId;
const buildState = $('Build State').first().json;
const rawOutput = $input.first().json.output.trim();
const userMessage = $('When chat message received').first().json.chatInput;
const userMessageLower = userMessage.toLowerCase();

// Detect intent keywords in user message for "add" case
const currencyCodes = ['USD','EUR','GBP','INR','JPY','AUD','CAD','CHF','CNY','SGD','HKD','NZD','SEK','NOK','DKK'];
const dateKeywords = ['yesterday','tomorrow','monday','tuesday','wednesday','thursday','friday','saturday','sunday','next','coming','hour','minute','week'];

const hasCurrency = userMessageLower.includes('convert') ||
                    userMessageLower.includes('conversion') ||
                    currencyCodes.filter(c => userMessageLower.includes(c.toLowerCase())).length >= 1;
const hasDate = dateKeywords.some(k => userMessageLower.includes(k)) ||
                userMessageLower.includes('date');
const userHasNewIntent = hasCurrency || hasDate;

// Check if user wants to add (either via ADD signal or by mentioning new intent)
const isAddSignal = rawOutput.toUpperCase().startsWith('ADD') ||
                    userMessageLower.includes('add') ||
                    userMessageLower.includes('also') ||
                    userMessageLower.includes('and also');

let intents = buildState.intents ?? [];
let nextStage;
let replyText;

if (rawOutput === 'CONFIRM' || rawOutput.toUpperCase().startsWith('CONFIRM')) {
  nextStage = 'INTENT_HANDLER';
  replyText = `Got it! I'll now process your requests.`;

} else if (rawOutput === 'CANCEL' || rawOutput.toUpperCase().startsWith('CANCEL')) {
  intents = [];
  nextStage = 'INTENT_CAPTURE';
  replyText = `No problem! What would you like help with?`;

} else if (rawOutput.toUpperCase().startsWith('REMOVE_CURRENCY')) {
  intents = intents.filter(i => i.type !== 'currency_conversion');
  nextStage = intents.length > 0 ? 'INTENT_CONFIRM' : 'INTENT_CAPTURE';
  const remaining = intents.map((i, idx) => {
    if (i.type === 'currency_conversion') return `${idx+1}. Currency: ${i.params.from} to ${i.params.to}`;
    if (i.type === 'date_time') return `${idx+1}. Date/time: ${i.params.query}`;
    return `${idx+1}. ${i.type}`;
  }).join('\n');
  replyText = intents.length > 0
    ? `Removed currency conversion. Remaining:\n${remaining}\nShall I proceed?`
    : `Removed currency conversion. No intents remaining. What would you like help with?`;

} else if (rawOutput.toUpperCase().startsWith('REMOVE_DATE')) {
  intents = intents.filter(i => i.type !== 'date_time');
  nextStage = intents.length > 0 ? 'INTENT_CONFIRM' : 'INTENT_CAPTURE';
  const remaining = intents.map((i, idx) => {
    if (i.type === 'currency_conversion') return `${idx+1}. Currency: ${i.params.from} to ${i.params.to}`;
    if (i.type === 'date_time') return `${idx+1}. Date/time: ${i.params.query}`;
    return `${idx+1}. ${i.type}`;
  }).join('\n');
  replyText = intents.length > 0
    ? `Removed date/time. Remaining:\n${remaining}\nShall I proceed?`
    : `Removed date/time. No intents remaining. What would you like help with?`;

} else if (isAddSignal && userHasNewIntent) {
  // User wants to add a new intent — extract it inline
  const newExtracted = [];

  if (hasCurrency) {
    const foundCurrencies = currencyCodes.filter(c => userMessageLower.includes(c.toLowerCase()));
    let from = 'USD'; let to = 'INR';
    if (foundCurrencies.length >= 2) {
      const toPattern = new RegExp(`(${foundCurrencies[0]})\\s+to\\s+(${foundCurrencies[1]})`, 'i');
      const reversePattern = new RegExp(`(${foundCurrencies[1]})\\s+to\\s+(${foundCurrencies[0]})`, 'i');
      if (toPattern.test(userMessage)) { from = foundCurrencies[0]; to = foundCurrencies[1]; }
      else if (reversePattern.test(userMessage)) { from = foundCurrencies[1]; to = foundCurrencies[0]; }
      else { from = foundCurrencies[0]; to = foundCurrencies[1]; }
    } else if (foundCurrencies.length === 1) { from = foundCurrencies[0]; }
    let date = 'latest';
    if (userMessageLower.includes('yesterday')) date = 'yesterday';
    else if (userMessageLower.includes('today')) date = 'today';
    newExtracted.push({ type: 'currency_conversion', params: { from, to, date }, status: 'pending' });
  }

  if (hasDate) {
    const words = userMessageLower.split(/\s+/);
    let dateWords = []; let capturing = false;
    const allDateKeywords = [...dateKeywords, 'today'];
    for (let i = 0; i < words.length; i++) {
      const word = words[i];
      if (allDateKeywords.some(k => word === k || word.startsWith(k))) capturing = true;
      if (capturing) {
        if (['and','for','also','plus'].includes(word) && dateWords.length > 0) break;
        dateWords.push(words[i]);
        if (dateWords.length >= 4) break;
      }
    }
    let query = dateWords.join(' ').trim();
    if (!query) query = 'today';
    if (query !== 'this' && query !== 'a') {
      newExtracted.push({ type: 'date_time', params: { query }, status: 'pending' });
    }
  }

  // Merge new intents with existing
  for (const incoming of newExtracted) {
    const alreadyExists = intents.some(e => e.type === incoming.type);
    if (!alreadyExists) intents.push(incoming);
  }

  const intentSummary = intents.map((i, idx) => {
    if (i.type === 'currency_conversion') return `${idx+1}. Currency: ${i.params.from} to ${i.params.to}${i.params.date !== 'latest' ? ` for ${i.params.date}` : ''}`;
    if (i.type === 'date_time') return `${idx+1}. Date/time: ${i.params.query}`;
    return `${idx+1}. ${i.type}`;
  }).join('\n');

  nextStage = 'INTENT_CONFIRM';
  replyText = `Updated! Here are your intents:\n${intentSummary}\nShall I proceed?`;

} else if (isAddSignal && !userHasNewIntent) {
  nextStage = 'INTENT_CAPTURE';
  replyText = `Sure! What would you like to add?`;

} else {
  // LLM gave conversational response — check if it's effectively a yes
  const outputLower = rawOutput.toLowerCase();
  const isImpliedConfirm = outputLower.includes('proceed') ||
                            outputLower.includes('processing') ||
                            outputLower.includes('got it') ||
                            outputLower.includes('confirmed') ||
                            outputLower.includes('will do');

  if (isImpliedConfirm) {
    nextStage = 'INTENT_HANDLER';
    replyText = `Got it! I'll now process your requests.`;
  } else {
    nextStage = 'INTENT_CONFIRM';
    replyText = rawOutput;
  }
}

return [{
  json: {
    sessionId,
    stage: nextStage,
    authenticated: buildState.auth?.authenticated ?? true,
    userId: buildState.auth?.userId,
    name: buildState.auth?.name,
    failedAttempts: buildState.auth?.failedAttempts ?? 0,
    intents: JSON.stringify(intents),
    intentRetryCount: buildState.intentRetryCount ?? 0,
    turnCount: buildState.turnCount ?? 1,
    lastAgentResponse: replyText,
    output: replyText
  }
}];

